UPDATE marketdata SET quote_depth_snapshot = quote_depth_snapshot || jsonb_build_object('spread_percentage', 
  ROUND(CAST(((CAST(quote_depth_snapshot->'quotes'->>'askquote' AS numeric) - CAST(quote_depth_snapshot->'quotes'->>'bidquote' AS numeric)) / CAST(quote_depth_snapshot->'quotes'->>'midquote' AS numeric)) * 100 AS numeric), 2));

SELECT COUNT(*) FROM marketdata WHERE (quote_depth_snapshot->>'spread_percentage') IS NOT NULL;
